// Curated tourist places — the only places seeded into the database.
// Images are Wikimedia Commons photos (verified reachable) taken from each place's Wikipedia article.

export interface PlaceSeed {
  name: string;
  slug: string;
  description: string;
  stateSlug: string;
  city: { name: string; slug: string; description: string };
  location: { latitude: number; longitude: number };
  category: string[];
  bestTimeToVisit: string;
  openingTime: string;
  closingTime: string;
  entryFee: string;
  images: string[];
  history: string;
  highlights: string[];
  thingsToKnow: string[];
  photography: boolean;
  weather: { summer: string; winter: string; monsoon: string };
  safetyTips: string[];
  transportation: {
    byFlight: { nearestAirport: string; distance: string; cabCost: string };
    byTrain: { nearestStation: string; distance: string; taxiFare: string };
    byBus: { busStand: string; autoFare: string };
    privateCab: string;
    bikeRental: string;
  };
  estimatedCost: {
    budget: CostTier;
    standard: CostTier;
    luxury: CostTier;
  };
  bestMonths: { month: string; temperature: string; crowd: string; recommendation: string }[];
  localFoods: string[];
  travelTips: { dos: string[]; donts: string[]; safety: string[] };
  localLanguage: string;
  emergencyNumbers: { police: string; ambulance: string; fire: string };
  faqs: { question: string; answer: string }[];
  rating: number;
  published: boolean;
  seo: { title: string; metaDescription: string; keywords: string[] };
}

type CostTier = { hotel: string; food: string; travel: string; tickets: string; shopping: string; total: string };

interface PlaceInput {
  name: string;
  slug: string;
  state: string;
  stateName: string;
  city: [name: string, description: string];
  coords: [lat: number, lng: number];
  category: string[];
  description: string;
  history: string;
  highlights: string[];
  thingsToKnow: string[];
  bestTimeToVisit: string;
  hours: [open: string, close: string];
  entryFee: string;
  photography?: boolean;
  weather: [summer: string, winter: string, monsoon: string];
  flight: [airport: string, distance: string, cab: string];
  train: [station: string, distance: string, fare: string];
  bus: [stand: string, auto: string];
  privateCab: string;
  bikeRental: string;
  /** Per-night hotel cost for budget / standard / luxury, and per-person tickets for the day. */
  cost: { hotel: [number, number, number]; tickets: number };
  bestMonths: [month: string, temperature: string, crowd: string, recommendation: string][];
  localFoods: string[];
  dos: string[];
  donts: string[];
  safety: string[];
  language: string;
  faqs?: [question: string, answer: string][];
  rating: number;
  keywords: string[];
}

const inr = (n: number) => `₹${n.toLocaleString('en-IN')}`;

function tier(hotel: number, food: number, travel: number, tickets: number, shopping: number): CostTier {
  return {
    hotel: inr(hotel),
    food: inr(food),
    travel: inr(travel),
    tickets: inr(tickets),
    shopping: inr(shopping),
    total: inr(hotel + food + travel + tickets + shopping),
  };
}

const citySlug = (state: string, name: string) =>
  `${state}-${name.toLowerCase().replace(/&/g, 'and').replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '')}`;

function place(p: PlaceInput): PlaceSeed {
  const [airport, airportDistance] = p.flight;
  return {
    name: p.name,
    slug: p.slug,
    description: p.description,
    stateSlug: p.state,
    city: { name: p.city[0], slug: citySlug(p.state, p.city[0]), description: p.city[1] },
    location: { latitude: p.coords[0], longitude: p.coords[1] },
    category: p.category,
    bestTimeToVisit: p.bestTimeToVisit,
    openingTime: p.hours[0],
    // The UI shows "opening – closing"; for all-day places show only "Open 24 hours".
    closingTime: p.hours[0] === p.hours[1] ? '' : p.hours[1],
    entryFee: p.entryFee,
    images: IMAGES[p.slug],
    history: p.history,
    highlights: p.highlights,
    thingsToKnow: p.thingsToKnow,
    photography: p.photography ?? true,
    weather: { summer: p.weather[0], winter: p.weather[1], monsoon: p.weather[2] },
    safetyTips: p.safety,
    transportation: {
      byFlight: { nearestAirport: airport, distance: airportDistance, cabCost: p.flight[2] },
      byTrain: { nearestStation: p.train[0], distance: p.train[1], taxiFare: p.train[2] },
      byBus: { busStand: p.bus[0], autoFare: p.bus[1] },
      privateCab: p.privateCab,
      bikeRental: p.bikeRental,
    },
    estimatedCost: {
      budget: tier(p.cost.hotel[0], 500, 500, p.cost.tickets, 500),
      standard: tier(p.cost.hotel[1], 1200, 1500, p.cost.tickets, 1500),
      luxury: tier(p.cost.hotel[2], 3500, 4000, p.cost.tickets, 5000),
    },
    bestMonths: p.bestMonths.map(([month, temperature, crowd, recommendation]) => ({ month, temperature, crowd, recommendation })),
    localFoods: p.localFoods,
    travelTips: { dos: p.dos, donts: p.donts, safety: p.safety },
    localLanguage: p.language,
    emergencyNumbers: { police: '100', ambulance: '108', fire: '101' },
    faqs: [
      { question: `What are the timings for ${p.name}?`, answer: p.hours[0] === p.hours[1] ? 'It is open 24 hours.' : `${p.hours[0]} to ${p.hours[1]}. ${p.thingsToKnow[0]}` },
      { question: `Is there an entry fee for ${p.name}?`, answer: p.entryFee },
      { question: `What is the best time to visit ${p.name}?`, answer: `${p.bestTimeToVisit}.` },
      { question: `How do I reach ${p.name}?`, answer: `The nearest airport is ${airport} (${airportDistance}) and the nearest railway station is ${p.train[0]} (${p.train[1]}).` },
      ...(p.faqs ?? []).map(([question, answer]) => ({ question, answer })),
    ],
    rating: p.rating,
    published: true,
    seo: {
      title: `${p.name}, ${p.stateName} — Travel Guide, Timings & Tips`,
      metaDescription: p.description.length > 155 ? `${p.description.slice(0, 152).trimEnd()}…` : p.description,
      keywords: [p.name, p.city[0], p.stateName, ...p.keywords],
    },
  };
}

